<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Huawei Online</title><style>:root{font-family:Arial;color:#172033;background:#f4f7fb}body{margin:0}.bar{background:#101827;color:#fff;padding:16px 24px;display:flex;justify-content:space-between}main{padding:24px;max-width:1450px;margin:auto}.panel{background:#fff;border-radius:12px;padding:20px;box-shadow:0 2px 12px #16213a18}.actions{display:flex;gap:10px;flex-wrap:wrap;margin:16px 0}.btn,button{border:0;border-radius:8px;padding:10px 14px;text-decoration:none;cursor:pointer;background:#1167d8;color:#fff}.secondary{background:#e8eef8;color:#172033}.search{padding:11px;width:320px;border:1px solid #ccd5df;border-radius:8px}table{width:100%;border-collapse:collapse}th,td{padding:10px;border-bottom:1px solid #e5eaf1;text-align:left}th{background:#edf3fb}.login{font-weight:bold;color:#075daf;text-decoration:none}.muted{color:#687386}.tablewrap{overflow:auto}</style></head><body>
<div class="bar"><strong>Huawei Online V2</strong><span>Usuário: <?=htmlspecialchars($user)?></span></div><main><div class="panel"><h2><span id="count">–</span> clientes Huawei online</h2><div class="actions"><button onclick="load()">Atualizar sessões</button><button onclick="testSnmp()">Testar SNMP</button><a class="btn" href="https://github.com/brsxdlols/huawei-online-mkauth#readme" target="_blank">README</a><a class="btn" href="/admin/addons/radius/index.php" onclick="window.open(this.href,'radiuslog','width=1100,height=720,scrollbars=yes');return false">Radius LOG</a><a class="btn secondary" href="/admin/addons/dashboard/">Dashboard</a><input id="filter" class="search" placeholder="Buscar nome, login, IP ou MAC"></div><p id="status" class="muted">Carregando dados do RADIUS…</p><div class="tablewrap"><table><thead><tr><th>Cliente / Login</th><th>IP</th><th>MAC</th><th>Porta</th><th>Início</th><th>Último update</th><th>Download</th><th>Upload</th></tr></thead><tbody id="rows"></tbody></table></div></div></main>
<script>let sessions=[];const fmt=n=>{n=Number(n||0);let u=['B','KB','MB','GB','TB'],i=0;while(n>=1024&&i<4){n/=1024;i++}return n.toFixed(i?2:0)+' '+u[i]},esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));function render(){let q=filter.value.toLowerCase(),list=sessions.filter(x=>[x.username,x.nome,x.framedipaddress,x.callingstationid].join(' ').toLowerCase().includes(q));rows.innerHTML=list.map(x=>`<tr><td><a class="login" href="detail.php?login=${encodeURIComponent(x.username)}">${esc(x.nome||x.username)}<br><small>${esc(x.username)}</small></a></td><td>${esc(x.framedipaddress)}</td><td>${esc(x.callingstationid)}</td><td>${esc(x.nasportid)}</td><td>${esc(x.acctstarttime)}</td><td>${esc(x.acctupdatetime)}</td><td>${fmt(x.acctoutputoctets)}</td><td>${fmt(x.acctinputoctets)}</td></tr>`).join('')}async function load(){let j=await fetch('api_sessions.php',{cache:'no-store'}).then(r=>r.json());if(!j.ok){status.textContent=j.error;return}sessions=j.sessions;count.textContent=j.count;render();status.textContent='Atualizado em '+new Date().toLocaleTimeString()+'. SNMP e SSH não rodam automaticamente.'}async function testSnmp(){status.textContent='Testando SNMP uma única vez…';let j=await fetch('api_health.php',{method:'POST'}).then(r=>r.json());status.textContent=j.message||j.error}filter.oninput=render;load();</script></body></html>
